input_schema:
Research scope with sub-questions and source strategy
{
  "scope": "object - Output from Stage 1",
  "search_access": {
    "web_search": "boolean",
    "database_access": ["string - Available databases"],
    "api_access": ["string - Available APIs"]
  }
}

output_schema:
Validated sources organized by sub-question
{
  "sources_by_question": [
    {
      "question_id": "string - Reference to sub-question",
      "sources": [
        {
          "id": "string - e.g., SRC-001",
          "title": "string",
          "url": "string",
          "type": "journal | report | news | government | company | other",
          "quality_tier": "tier-1 | tier-2 | tier-3",
          "publication_date": "string",
          "author_organization": "string",
          "relevance_score": "number - 1-10",
          "key_claims": [
            {
              "claim": "string",
              "page_section": "string",
              "quote": "string | null"
            }
          ],
          "limitations": ["string - Bias, recency, scope issues"],
          "verification_status": "verified | unverified | conflicting"
        }
      ]
    }
  ],
  "source_summary": {
    "total_sources": "number",
    "by_tier": {
      "tier-1": "number",
      "tier-2": "number",
      "tier-3": "number"
    },
    "by_type": {
      "journal": "number",
      "report": "number",
      "news": "number",
      "government": "number",
      "company": "number"
    }
  },
  "coverage_assessment": {
    "well_covered": ["string - Questions with strong sources"],
    "partially_covered": ["string - Questions with some sources"],
    "gaps": ["string - Questions lacking adequate sources"]
  },
  "conflicting_sources": [
    {
      "topic": "string",
      "source_1": "string - Source ID",
      "source_2": "string - Source ID",
      "nature_of_conflict": "string",
      "resolution_approach": "string"
    }
  ]
}
